def bi(es,en='',tag='span',cls=''):
 return f'<{tag} class="{cls}" data-es="{E(es,quote=True)}" data-en="{E(en or es,quote=True)}">{es}</{tag}>'
def image(name,alt,cls='',lazy=True):return f'<img class="{cls}" src="../assets/{name}.webp" alt="{E(alt)}" width="1400" height="1000" '+('loading="lazy" 'if lazy else 'fetchpriority="high" ')+ 'decoding="async">'
def intro(kicker,title,lead=''):
 return f'<div class="section-head"><div><p class="eyebrow">{kicker}</p><h2>{title}</h2></div>'+ (f'<p>{lead}</p>'if lead else '')+'</div>'
def faq(items):
 return '<section class="section faq" id="preguntas">'+intro('UN POCO MÁS DE INFORMACIÓN','Resolvemos lo importante.')+'<div class="faq-grid">'+''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>'for q,a in items)+'</div></section>'
def form_block(d,guest=False):
 opts=d.get('serviceOptions',d.get('services',[]));label='Preparar solicitud'if guest else d['cta'];title='¿Te ayudamos con algo?'if guest else 'El siguiente paso empieza aquí.'
 return f'''<section class="section contact-section" id="contacto"><div><p class="eyebrow">{'TU CONCIERGE DIGITAL'if guest else 'HABLEMOS'}</p><h2>{title}</h2><p>{'Prepara una petición para el equipo del alojamiento.'if guest else 'Cuéntanos qué necesitas y prepara tu consulta con todos los detalles.'}</p><div class="contact-note"><span class="status-dot"></span><p>Modo demostración. Puedes probar el flujo sin enviar información a ningún negocio.</p></div><p class="fine">Campos con * obligatorios. La solicitud se genera en tu navegador; no equivale a una reserva confirmada.</p></div><form class="request-form" data-brand="{E(d['name'])}"><div class="form-row"><label>Nombre *<input name="name" autocomplete="name" required maxlength="80" placeholder="Tu nombre"></label><label>{'Habitación / apartamento'if guest else 'Correo electrónico *'}<input name="{'room'if guest else 'email'}" {'type="email" required autocomplete="email"'if not guest else 'maxlength="40"'} placeholder="{'Ejemplo: 204'if guest else 'nombre@ejemplo.com'}"></label></div><label>{'¿Qué necesitas?'if guest else 'Servicio'}<select name="service">{''.join(f'<option>{E(o)}</option>'for o in opts)}</select></label><div class="form-row"><label>Fecha preferida *<input name="date" type="date" required></label><label>Hora preferida<select name="time"><option>09:00</option><option>11:00</option><option>13:00</option><option>16:00</option><option>18:00</option><option>20:00</option></select></label></div><label>Detalles<textarea name="message" rows="3" maxlength="2000" placeholder="Añade preferencias o información útil para tu solicitud."></textarea></label><label class="check"><input type="checkbox" name="consent" required><span>Entiendo que es una demo y que no se enviará una reserva real.</span></label><button class="btn" type="submit">{label} <span aria-hidden="true">↗</span></button><div class="request-result" hidden><h3>Solicitud preparada.</h3><p>No enviada. Revisa los detalles:</p><textarea readonly aria-label="Resumen de la solicitud" rows="6"></textarea><div class="button-row"><button type="button" class="btn outline" data-copy-result>Copiar</button><button type="button" class="btn outline" data-download-result>Descargar</button><button type="button" class="btn outline" data-calendar>Guardar recordatorio</button></div><p class="form-status" role="status"></p></div></form></section>'''
