 g=d.get('guest',False);c=d['colors'];nav=[('guia','Tu estancia'),('experiencias','Descubre'),('contacto','Ayuda')]if g else [('coleccion',{'menu':'La carta','classes':'Clases','properties':'Viviendas','courses':'Cursos'}.get(d.get('feature'),'Servicios')),('historia','El espacio'),('contacto','Contacto')]
